import {products,addDays,notice,hours,price,day,validate,create,accept,reject,edit,cancel,helper,advance,seed} from './rules.mjs';
const $=id=>document.getElementById(id),key='batch-order-book-v1';
let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(key))||seed();if(!Array.isArray(state.orders)||!Array.isArray(state.helpers)||!state.today)throw Error();}catch{state=seed();storageOK=false;}
let filter='all',editing=null,confirmation=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateObj=d=>new Date(d+'T12:00:00Z');
const fmt=(d,opts={month:'short',day:'numeric'})=>new Intl.DateTimeFormat('en-CA',{...opts,timeZone:'UTC'}).format(dateObj(d));
const money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);
function monday(d){const date=dateObj(d);return addDays(d,-((date.getUTCDay()+6)%7));}
let weekStart=monday(state.today);
let timer;function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('visible'),5000);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageOK=false;toast('Browser storage is unavailable. Changes will last only until this page closes.');}render();}
function confirmAction(title,text,button,fn){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-yes').textContent=button;confirmation=fn;$('confirm-dialog').showModal();}
$('confirm-no').onclick=()=>$('confirm-dialog').close();$('confirm-yes').onclick=()=>{const fn=confirmation;$('confirm-dialog').close();fn?.();};
function render(){
 $('practice-date').textContent=fmt(state.today,{weekday:'long',month:'short',day:'numeric',year:'numeric'});
 const end=addDays(weekStart,6),dates=Array.from({length:7},(_,i)=>addDays(weekStart,i));
 $('range').textContent=`${fmt(weekStart)} – ${fmt(end)}`;$('week-label').textContent=`${fmt(weekStart)} – ${fmt(end)}`;
 const totals=dates.reduce((acc,d)=>{const summary=day(state,d);acc.count+=summary.count;acc.sales+=summary.revenue;return acc;},{count:0,sales:0});const costs=state.helpers.filter(d=>d>=weekStart&&d<=end).length*100;
 $('metric-orders').textContent=totals.count;$('metric-sales').textContent=money(totals.sales);$('metric-costs').textContent=money(costs);$('metric-net').textContent=money(totals.sales-costs);
 $('days').innerHTML=dates.map(date=>{const d=day(state,date),booked=state.helpers.includes(date),allowed=notice(date,state.today);return `<article class="day ${date===state.today?'today':''}"><div class="day-name">${fmt(date,{weekday:'short'})}${date===state.today?'<i class="today-label" title="Practice today"></i>':''}</div><div class="day-number">${Number(date.slice(-2))}</div><div class="capacity"><strong>${d.used}h</strong> <span>/ ${d.capacity}h booked</span></div><div class="bar"><span style="width:${Math.min(100,d.used/d.capacity*100)}%"></span></div><div class="day-count">${d.count} ${d.count===1?'order':'orders'} · ${d.capacity-d.used}h left</div><button class="helper-button ${booked?'booked':''}" data-helper="${date}" ${booked||!allowed?'disabled':''} title="${booked?'Helper booked: four extra hours, $100':!allowed?'Two calendar days’ notice required':'Book four extra hours for $100'}">${booked?'✓ Helper booked':!allowed?'Booking closed':'+ Helper · $100'}</button></article>`;}).join('');
 const q=$('search').value.toLowerCase().trim();const orders=state.orders.filter(o=>(filter==='all'||(filter==='closed'?!['requested','accepted'].includes(o.status):o.status===filter))&&o.customer.toLowerCase().includes(q)).sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id);
 $('total-count').textContent=state.orders.length;$('pending-count').textContent=state.orders.filter(o=>o.status==='requested').length;
 $('order-rows').innerHTML=orders.map(o=>{let actions='';if(o.status==='requested')actions=`<button data-action="accept" data-id="${o.id}" class="accept">Accept</button><button data-action="reject" data-id="${o.id}">Reject</button>`;if(['requested','accepted'].includes(o.status))actions+=`<button data-action="edit" data-id="${o.id}" class="quiet">Edit</button><button data-action="cancel" data-id="${o.id}" class="quiet">Cancel</button>`;const names={'requested':'Requested','accepted':'Accepted','rejected':'Rejected','cancelled':'Cancelled','picked-up':'Picked up'};return `<tr><td><div class="customer-cell"><span class="avatar">${esc(o.customer.slice(0,1).toUpperCase())}</span><div><div class="customer-name">${esc(o.customer)}</div><div class="order-id">#${String(o.id).padStart(3,'0')}</div></div></div></td><td>${o.quantity} ${o.product==='cake'?(o.quantity===1?'cake':'cakes'):(o.quantity===1?'dozen cupcakes':'dozen cupcakes')}<div class="product-sub">${o.product==='cake'?'$120 per cake':'$40 per dozen'}</div></td><td>${fmt(o.date,{weekday:'short',month:'short',day:'numeric'})}</td><td>${hours(o)}h</td><td><strong>${money(price(o))}</strong></td><td><span class="status ${o.status}">${names[o.status]}</span>${o.reason?`<div class="reason">${esc(o.reason)}</div>`:''}</td><td><div class="row-actions">${actions||'<span class="product-sub">Complete</span>'}</div></td></tr>`;}).join('');$('empty').hidden=orders.length>0;
 document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));
}
function openForm(o=null){editing=o?.id??null;$('form-title').textContent=o?'Edit this order':'A new batch';$('save-order').textContent=o?'Save changes':'Add order';$('customer').value=o?.customer??'';$('product').value=o?.product??'cupcakes';$('quantity').value=o?.quantity??1;$('pickup-date').value=o?.date??addDays(state.today,2);$('form-error').textContent='';estimate();$('order-dialog').showModal();}
function estimate(){const o={product:$('product').value,quantity:Number($('quantity').value)};$('quantity-label').textContent=o.product==='cake'?'Cakes':'Dozens';$('estimate-hours').textContent=`${Number.isFinite(hours(o))?hours(o):0}h of oven time`;$('estimate-price').textContent=money(Number.isFinite(price(o))?price(o):0);}
$('new-order').onclick=()=>openForm();$('close-dialog').onclick=$('cancel-dialog').onclick=()=>$('order-dialog').close();$('product').onchange=estimate;$('quantity').oninput=estimate;
$('order-form').onsubmit=e=>{e.preventDefault();const input={customer:$('customer').value.trim(),product:$('product').value,quantity:Number($('quantity').value),date:$('pickup-date').value};if(editing!==null){const err=edit(state,editing,input);if(err){$('form-error').textContent=err;return;}save();$('order-dialog').close();toast('Order updated. Capacity and totals are up to date.');}else{const err=validate(state,input);if(err){$('form-error').textContent=err;return;}const o=create(state,input);save();$('order-dialog').close();filter='requested';render();toast(`Order #${String(o.id).padStart(3,'0')} added. Ready for your decision.`);}};
$('days').onclick=e=>{const b=e.target.closest('[data-helper]');if(!b||b.disabled)return;const date=b.dataset.helper;confirmAction('A helping hand?',`Book a helper for ${fmt(date,{weekday:'long',month:'short',day:'numeric'})}? This adds four hours of capacity and a $100 cost to this practice day.`,'Book helper · $100',()=>{const err=helper(state,date);if(err)return toast(err);save();toast('Helper booked. You now have 12 hours of capacity.');});};
$('order-rows').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),o=state.orders.find(o=>o.id===id),action=b.dataset.action;if(action==='edit')return openForm(o);if(action==='accept'){const err=accept(state,id);if(err)return toast(err);save();toast(`${o.customer}’s order accepted.`);return;}confirmAction(action==='reject'?'Reject this request?':'Cancel this order?',`${o.customer} · ${o.quantity} ${products[o.product].name.toLowerCase()} · ${fmt(o.date)}. ${action==='cancel'?'Cancellations need two calendar days’ notice.':'The request will be kept in your closed orders.'}`,action==='reject'?'Reject request':'Cancel order',()=>{const err=action==='reject'?reject(state,id):cancel(state,id);if(err)return toast(err);save();toast(action==='reject'?'Request rejected.':'Order cancelled. Reserved capacity released.');});};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('search').oninput=render;
$('prev-week').onclick=()=>{weekStart=addDays(weekStart,-7);render();};$('next-week').onclick=()=>{weekStart=addDays(weekStart,7);render();};
$('advance').onclick=()=>{const n=state.orders.filter(o=>o.status==='requested').length;confirmAction('Wrap up this practice day?',`Review ${n} remaining ${n===1?'request':'requests'} in arrival order. Requests that fit will be accepted; others will be rejected with a reason. Today’s accepted pickups will be marked picked up at 5 pm. Then the practice clock moves forward one day.`,'Accept & next day',()=>{const r=advance(state);weekStart=monday(state.today);save();toast(`${r.accepted} accepted · ${r.rejected} rejected. Practice day advanced.`);});};
$('reset').onclick=()=>confirmAction('Start fresh?', 'This removes your browser’s practice orders and helper bookings and restores the three sample orders.','Reset samples',()=>{state=seed();weekStart=monday(state.today);filter='all';$('search').value='';save();toast('Sample workspace restored.');});
render();if(!storageOK)toast('Saved data could not be loaded. This session uses fresh samples.');
